import * as React from "react";
import {
  Animated,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { Icon, type IconName } from "@/components/native/icon";
import { focusRing } from "@/components/native/input";
import { Backdrop, useBackHandler, useOverlayTransition } from "@/components/native/overlay";
import { Portal } from "@/components/native/portal";
import { useTheme } from "@/components/native/theme";

export type SelectOption = { value: string; label: string; description?: string; icon?: IconName };

export type SelectProps = {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  /** Title of the picker sheet. */
  title?: string;
  /** Adds a filter field to the sheet. Defaults to true with 8+ options. */
  searchable?: boolean;
  invalid?: boolean;
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
};

export function Select({
  options,
  value,
  defaultValue,
  onValueChange,
  placeholder = "Select an option",
  title,
  searchable,
  invalid,
  disabled,
  style,
}: SelectProps) {
  const { colors, shadow } = useTheme();
  const [inner, setInner] = React.useState(defaultValue);
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const current = value ?? inner;
  const selected = options.find((o) => o.value === current);
  const { mounted, progress } = useOverlayTransition(open);
  const close = React.useCallback(() => setOpen(false), []);
  useBackHandler(open, close);

  const canSearch = searchable ?? options.length >= 8;
  const filtered = query
    ? options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase()))
    : options;

  const choose = (v: string) => {
    if (value === undefined) setInner(v);
    onValueChange?.(v);
    setOpen(false);
    setQuery("");
  };

  return (
    <>
      <Pressable
        accessibilityRole="combobox"
        accessibilityState={{ expanded: open, disabled }}
        disabled={disabled}
        onPress={() => setOpen(true)}
        style={[
          styles.trigger,
          {
            backgroundColor: disabled ? colors.muted : colors.background,
            borderColor: invalid ? colors.destructive : open ? colors.brand : colors.input,
            opacity: disabled ? 0.6 : 1,
          },
          open && focusRing(colors.brand),
          style,
        ]}
      >
        {selected?.icon && <Icon name={selected.icon} size={18} />}
        <Text
          numberOfLines={1}
          style={[styles.triggerText, { color: selected ? colors.foreground : colors.subtle }]}
        >
          {selected?.label ?? placeholder}
        </Text>
        <Icon name="chevrons-up-down" size={16} color={colors.mutedForeground} />
      </Pressable>

      {mounted && (
        <Portal>
          <View style={[StyleSheet.absoluteFill, styles.end]}>
            <Backdrop progress={progress} onPress={close} />
            <Animated.View
              accessibilityViewIsModal
              style={[
                styles.sheet,
                shadow(4),
                {
                  backgroundColor: colors.card,
                  transform: [
                    {
                      translateY: progress.interpolate({
                        inputRange: [0, 1],
                        outputRange: [420, 0],
                      }),
                    },
                  ],
                },
              ]}
            >
              <View style={[styles.handle, { backgroundColor: colors.borderStrong }]} />
              {title && <Text style={[styles.title, { color: colors.foreground }]}>{title}</Text>}
              {canSearch && (
                <View style={[styles.search, { backgroundColor: colors.muted }]}>
                  <Icon name="search" size={16} color={colors.mutedForeground} />
                  <TextInput
                    value={query}
                    onChangeText={setQuery}
                    placeholder="Search"
                    placeholderTextColor={colors.mutedForeground}
                    style={[styles.searchInput, { color: colors.foreground }]}
                  />
                </View>
              )}
              <ScrollView style={styles.list} keyboardShouldPersistTaps="handled">
                {filtered.map((o) => {
                  const active = o.value === current;
                  return (
                    <Pressable
                      key={o.value}
                      accessibilityRole="menuitem"
                      accessibilityState={{ selected: active }}
                      onPress={() => choose(o.value)}
                      style={({ pressed }) => [
                        styles.option,
                        { backgroundColor: pressed || active ? colors.accent : "transparent" },
                      ]}
                    >
                      {o.icon && <Icon name={o.icon} size={18} />}
                      <View style={{ flex: 1 }}>
                        <Text style={[styles.optionText, { color: colors.foreground }]}>
                          {o.label}
                        </Text>
                        {o.description && (
                          <Text style={[styles.optionDesc, { color: colors.mutedForeground }]}>
                            {o.description}
                          </Text>
                        )}
                      </View>
                      {active && (
                        <Icon name="check" size={18} strokeWidth={2.5} color={colors.brand} />
                      )}
                    </Pressable>
                  );
                })}
                {filtered.length === 0 && (
                  <Text style={[styles.empty, { color: colors.mutedForeground }]}>No results</Text>
                )}
              </ScrollView>
            </Animated.View>
          </View>
        </Portal>
      )}
    </>
  );
}

const styles = StyleSheet.create({
  trigger: {
    height: 48,
    borderWidth: 1,
    borderRadius: 13,
    paddingHorizontal: 14,
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
  },
  triggerText: { flex: 1, fontSize: 16 },
  end: { justifyContent: "flex-end" },
  sheet: {
    borderTopLeftRadius: 28,
    borderTopRightRadius: 28,
    paddingHorizontal: 12,
    paddingTop: 8,
    paddingBottom: 28,
    maxHeight: "75%",
  },
  handle: { alignSelf: "center", width: 36, height: 5, borderRadius: 3, marginBottom: 10 },
  title: { fontSize: 17, fontWeight: "600", textAlign: "center", marginBottom: 12 },
  search: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    height: 40,
    borderRadius: 12,
    paddingHorizontal: 12,
    marginHorizontal: 4,
    marginBottom: 8,
  },
  searchInput: { flex: 1, fontSize: 15, height: "100%", outlineStyle: "none" } as never,
  list: { flexGrow: 0 },
  option: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    paddingHorizontal: 14,
    minHeight: 50,
    paddingVertical: 10,
    borderRadius: 14,
  },
  optionText: { fontSize: 16 },
  optionDesc: { fontSize: 13, marginTop: 1 },
  empty: { textAlign: "center", paddingVertical: 24, fontSize: 14 },
});

import * as React from "react";
import {
  Platform,
  Pressable,
  StyleSheet,
  TextInput,
  View,
  type StyleProp,
  type TextInputProps,
  type ViewStyle,
} from "react-native";
import { Icon, type IconName } from "@/components/native/icon";
import { alpha, useTheme } from "@/components/native/theme";

export type InputProps = Omit<TextInputProps, "style"> & {
  leftIcon?: IconName;
  rightIcon?: IconName;
  /** Show a clear button while there is text. */
  clearable?: boolean;
  /** Show an eye toggle for `secureTextEntry` fields. */
  revealable?: boolean;
  invalid?: boolean;
  size?: "sm" | "md" | "lg";
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
};

const heights = { sm: 40, md: 48, lg: 56 };

/** A soft 3pt halo around a focused field. */
export function focusRing(color: string): ViewStyle {
  return Platform.OS === "web"
    ? ({ boxShadow: `0 0 0 3px ${alpha(color, 0.18)}` } as ViewStyle)
    : { outlineColor: alpha(color, 0.22), outlineWidth: 3, outlineStyle: "solid" };
}

export const Input = React.forwardRef<TextInput, InputProps>(function Input(
  {
    leftIcon,
    rightIcon,
    clearable,
    revealable,
    invalid,
    size = "md",
    disabled,
    secureTextEntry,
    value,
    defaultValue,
    onChangeText,
    onFocus,
    onBlur,
    style,
    ...props
  },
  ref,
) {
  const { colors } = useTheme();
  const [focused, setFocused] = React.useState(false);
  const [hidden, setHidden] = React.useState(true);
  const [inner, setInner] = React.useState(defaultValue ?? "");
  const text = value ?? inner;
  const inputRef = React.useRef<TextInput>(null);
  React.useImperativeHandle(ref, () => inputRef.current as TextInput);

  const change = (t: string) => {
    if (value === undefined) setInner(t);
    onChangeText?.(t);
  };

  const ring = invalid ? colors.destructive : colors.brand;

  return (
    <View
      style={[
        styles.wrap,
        {
          height: heights[size],
          borderRadius: size === "lg" ? 16 : 13,
          backgroundColor: disabled ? colors.muted : colors.background,
          borderColor: invalid ? colors.destructive : focused ? ring : colors.input,
          opacity: disabled ? 0.6 : 1,
        },
        focused && focusRing(ring),
        style,
      ]}
    >
      {leftIcon && (
        <Icon
          name={leftIcon}
          size={18}
          color={focused ? colors.foreground : colors.mutedForeground}
        />
      )}
      <TextInput
        ref={inputRef}
        editable={!disabled}
        value={text}
        onChangeText={change}
        secureTextEntry={secureTextEntry && hidden}
        placeholderTextColor={colors.subtle}
        selectionColor={colors.brand}
        cursorColor={colors.brand}
        onFocus={(e) => {
          setFocused(true);
          onFocus?.(e);
        }}
        onBlur={(e) => {
          setFocused(false);
          onBlur?.(e);
        }}
        aria-invalid={invalid}
        style={[styles.input, { color: colors.foreground, fontSize: size === "sm" ? 14 : 16 }]}
        {...props}
      />
      {clearable && text.length > 0 && !disabled && (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel="Clear text"
          hitSlop={10}
          onPress={() => {
            change("");
            inputRef.current?.focus();
          }}
          style={[styles.clear, { backgroundColor: colors.subtle }]}
        >
          <Icon name="x" size={11} strokeWidth={3} color={colors.background} />
        </Pressable>
      )}
      {secureTextEntry && revealable && (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={hidden ? "Show password" : "Hide password"}
          hitSlop={10}
          onPress={() => setHidden((h) => !h)}
        >
          <Icon name={hidden ? "eye" : "eye-off"} size={18} color={colors.mutedForeground} />
        </Pressable>
      )}
      {rightIcon && <Icon name={rightIcon} size={18} color={colors.mutedForeground} />}
    </View>
  );
});

const styles = StyleSheet.create({
  wrap: {
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
    paddingHorizontal: 14,
    borderWidth: 1,
  },
  input: { flex: 1, height: "100%", paddingVertical: 0, outlineStyle: "none" } as never,
  clear: { width: 18, height: 18, borderRadius: 9, alignItems: "center", justifyContent: "center" },
});

/**
 * Shared overlay plumbing for Dialog, Sheet, Select, Drawer…
 * - useOverlayTransition: keeps the tree mounted while the exit animation runs.
 * - useBackHandler: Android back button (Escape key on web).
 * - Backdrop: an animated, pressable scrim.
 */
import * as React from "react";
import { Animated, BackHandler, Easing, Platform, Pressable, StyleSheet } from "react-native";
import { nativeDriver, useTheme } from "@/components/native/theme";

export function useOverlayTransition(
  open: boolean,
  { enter = "spring", duration = 220 }: { enter?: "spring" | "timing"; duration?: number } = {},
) {
  const progress = React.useRef(new Animated.Value(0)).current;
  const [mounted, setMounted] = React.useState(open);
  const target = React.useRef(open ? 1 : 0);
  const alive = React.useRef(true);

  React.useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  const run = React.useCallback(
    (to: 0 | 1) => {
      target.current = to;
      const anim =
        to === 1
          ? enter === "spring"
            ? Animated.spring(progress, {
                toValue: 1,
                useNativeDriver: nativeDriver,
                damping: 22,
                stiffness: 260,
                mass: 0.9,
              })
            : Animated.timing(progress, {
                toValue: 1,
                duration,
                easing: Easing.out(Easing.cubic),
                useNativeDriver: nativeDriver,
              })
          : Animated.timing(progress, {
              toValue: 0,
              duration: Math.round(duration * 0.8),
              easing: Easing.in(Easing.cubic),
              useNativeDriver: nativeDriver,
            });

      anim.start(({ finished }) => {
        if (!alive.current || target.current !== to) return; // superseded or unmounted
        if (!finished) {
          // Interrupted, e.g. the animated views re-attached (StrictMode, portal
          // remount). Resume from the current value on the next frame.
          requestAnimationFrame(() => alive.current && target.current === to && run(to));
          return;
        }
        if (to === 0) setMounted(false);
      });
    },
    [enter, duration, progress],
  );

  React.useEffect(() => {
    if (open) {
      setMounted(true);
      run(1);
    } else if (target.current === 1) {
      run(0);
    }
  }, [open, run]);

  return { mounted, progress };
}

/** Closes on the Android hardware back button, or Escape on the web, while `active`. */
export function useBackHandler(active: boolean, onBack: () => void) {
  React.useEffect(() => {
    if (!active) return;
    if (Platform.OS === "web") {
      const onKey = (e: KeyboardEvent) => e.key === "Escape" && onBack();
      window.addEventListener("keydown", onKey);
      return () => window.removeEventListener("keydown", onKey);
    }
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      onBack();
      return true;
    });
    return () => sub.remove();
  }, [active, onBack]);
}

export function Backdrop({
  progress,
  onPress,
  dismissible = true,
}: {
  progress: Animated.Value;
  onPress?: () => void;
  dismissible?: boolean;
}) {
  const { colors } = useTheme();
  return (
    <Animated.View
      style={[StyleSheet.absoluteFill, { backgroundColor: colors.overlay, opacity: progress }]}
    >
      <Pressable
        accessibilityRole="button"
        accessibilityLabel="Close"
        style={StyleSheet.absoluteFill}
        onPress={dismissible ? onPress : undefined}
      />
    </Animated.View>
  );
}

/**
 * Portal + PortalHost.
 *
 * Overlays (Dialog, Sheet, Select, Toast…) render into the nearest <PortalHost>
 * so they sit above your navigation. Put one at the root of your app:
 *
 *   <PortalHost>
 *     <Stack />
 *   </PortalHost>
 *
 * Without a host, overlays fall back to a transparent React Native <Modal>.
 */
import * as React from "react";
import { Modal, StyleSheet, View } from "react-native";

type Store = {
  set: (key: string, node: React.ReactNode) => void;
  remove: (key: string) => void;
};

const PortalContext = React.createContext<Store | null>(null);

export function PortalHost({ children }: { children?: React.ReactNode }) {
  const [nodes, setNodes] = React.useState<[string, React.ReactNode][]>([]);

  const store = React.useMemo<Store>(
    () => ({
      set: (key, node) =>
        setNodes((prev) => {
          const i = prev.findIndex(([k]) => k === key);
          if (i === -1) return [...prev, [key, node]];
          const next = prev.slice();
          next[i] = [key, node];
          return next;
        }),
      remove: (key) => setNodes((prev) => prev.filter(([k]) => k !== key)),
    }),
    [],
  );

  return (
    <PortalContext.Provider value={store}>
      <View style={styles.root}>
        {children}
        <View pointerEvents="box-none" style={StyleSheet.absoluteFill}>
          {nodes.map(([key, node]) => (
            <React.Fragment key={key}>{node}</React.Fragment>
          ))}
        </View>
      </View>
    </PortalContext.Provider>
  );
}

export function Portal({ children }: { children: React.ReactNode }) {
  const store = React.useContext(PortalContext);
  const key = React.useId();

  React.useLayoutEffect(() => {
    store?.set(key, children);
  }, [store, key, children]);

  React.useLayoutEffect(() => {
    return () => store?.remove(key);
  }, [store, key]);

  if (store) return null;
  return (
    <Modal transparent visible animationType="none" statusBarTranslucent>
      {children}
    </Modal>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
});

/**
 * Synapse UI Native: design tokens and theme.
 *
 * Every native component reads its colors from `useTheme()`. Wrap your app in
 * <ThemeProvider> to force a scheme or override colors; without it the system
 * color scheme is used.
 */
import * as React from "react";
import { Platform, useColorScheme, type ViewStyle } from "react-native";

export const palette = {
  light: {
    background: "#ffffff",
    foreground: "#0a0a0b",
    card: "#ffffff",
    cardForeground: "#0a0a0b",
    surface: "#fafafa",
    surfaceStrong: "#f4f4f5",
    muted: "#f4f4f5",
    mutedForeground: "#71717a",
    subtle: "#a1a1aa",
    border: "#e7e7ea",
    borderStrong: "#d4d4d8",
    input: "#e4e4e7",
    ring: "#a1a1aa",
    primary: "#18181b",
    primaryForeground: "#fafafa",
    secondary: "#f4f4f5",
    secondaryForeground: "#18181b",
    accent: "#f4f4f5",
    accentForeground: "#18181b",
    brand: "#2563eb",
    brandForeground: "#ffffff",
    brandSoft: "#eff4ff",
    success: "#16a34a",
    successSoft: "#ecfdf3",
    warning: "#d97706",
    warningSoft: "#fffaeb",
    destructive: "#dc2626",
    destructiveForeground: "#ffffff",
    destructiveSoft: "#fef2f2",
    overlay: "rgba(9, 9, 11, 0.42)",
    shadow: "#0a0a0b",
  },
  dark: {
    background: "#09090b",
    foreground: "#f4f4f5",
    card: "#111113",
    cardForeground: "#f4f4f5",
    surface: "#111113",
    surfaceStrong: "#18181b",
    muted: "#18181b",
    mutedForeground: "#a1a1aa",
    subtle: "#71717a",
    border: "#232327",
    borderStrong: "#2e2e33",
    input: "#27272a",
    ring: "#52525b",
    primary: "#f4f4f5",
    primaryForeground: "#09090b",
    secondary: "#1c1c1f",
    secondaryForeground: "#f4f4f5",
    accent: "#1f1f23",
    accentForeground: "#f4f4f5",
    brand: "#3b82f6",
    brandForeground: "#ffffff",
    brandSoft: "#172036",
    success: "#4ade80",
    successSoft: "#0f2418",
    warning: "#fbbf24",
    warningSoft: "#2a2110",
    destructive: "#f87171",
    destructiveForeground: "#0a0a0b",
    destructiveSoft: "#2a1414",
    overlay: "rgba(0, 0, 0, 0.62)",
    shadow: "#000000",
  },
};

export type ThemeColors = typeof palette.light;
export type ColorScheme = "light" | "dark";

export const radius = { xs: 6, sm: 8, md: 12, lg: 16, xl: 20, "2xl": 24, "3xl": 32, full: 9999 };

/** 4pt spacing scale: space(4) === 16. */
export const space = (n: number) => n * 4;

export const fontSize = {
  xs: 12,
  sm: 14,
  base: 16,
  lg: 18,
  xl: 20,
  "2xl": 24,
  "3xl": 30,
  "4xl": 36,
};

export const fontWeight = {
  regular: "400",
  medium: "500",
  semibold: "600",
  bold: "700",
} as const;

export const fontFamily = {
  mono: Platform.select({
    ios: "Menlo",
    android: "monospace",
    default: "ui-monospace, Menlo, monospace",
  }),
};

/** Animated: use the native driver everywhere except react-native-web. */
export const nativeDriver = Platform.OS !== "web";

/** Cross-platform elevation. Level 0–4. */
export function shadow(level: 0 | 1 | 2 | 3 | 4, scheme: ColorScheme = "light"): ViewStyle {
  if (level === 0) return {};
  const dark = scheme === "dark";
  const y = [0, 1, 4, 10, 18][level];
  const blur = [0, 3, 12, 28, 44][level];
  const alpha = (dark ? [0, 0.4, 0.5, 0.55, 0.6] : [0, 0.06, 0.08, 0.12, 0.16])[level];
  if (Platform.OS === "web") {
    return { boxShadow: `0px ${y}px ${blur}px rgba(0,0,0,${alpha})` } as ViewStyle;
  }
  return {
    shadowColor: "#000",
    shadowOffset: { width: 0, height: y },
    shadowOpacity: alpha,
    shadowRadius: blur / 2,
    elevation: level * 3,
  };
}

/** Hex color to rgba(). */
export function alpha(hex: string, a: number) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.replace(/./g, (c) => c + c) : h, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

type ThemeValue = {
  scheme: ColorScheme;
  colors: ThemeColors;
  radius: typeof radius;
  space: typeof space;
  fontSize: typeof fontSize;
  fontWeight: typeof fontWeight;
  shadow: (level: 0 | 1 | 2 | 3 | 4) => ViewStyle;
};

const ThemeContext = React.createContext<{
  scheme?: ColorScheme;
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
} | null>(null);

export function ThemeProvider({
  scheme,
  colors,
  children,
}: {
  /** Force a scheme. Defaults to the device setting. */
  scheme?: ColorScheme;
  /** Override tokens per scheme, e.g. `{ light: { brand: "#7c3aed" } }`. */
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ scheme, colors }), [scheme, colors]);
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeValue {
  const ctx = React.useContext(ThemeContext);
  const system = useColorScheme();
  const scheme: ColorScheme = ctx?.scheme ?? (system === "dark" ? "dark" : "light");
  return React.useMemo(
    () => ({
      scheme,
      colors: { ...palette[scheme], ...(ctx?.colors?.[scheme] ?? {}) },
      radius,
      space,
      fontSize,
      fontWeight,
      shadow: (level: 0 | 1 | 2 | 3 | 4) => shadow(level, scheme),
    }),
    [scheme, ctx?.colors],
  );
}
